// 科技信息 · 风格样片。标准分镜：标题 → 花字 → 图片容器与高亮 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、grid()（底纹网格）、brackets()（角标框）、typeOn()（等宽逐字打出与光标）、checkbox()（先描框后填充）、
// rollNumber()（数字滚动）、lineChart()（折线生长）、CUTS + cutClip() + wipe()（扫线硬切：线后就是新场景），
// 以及 layers() 的分层写法：会位移、会伸展的元素各成一层，运行时据此做运动模糊；逐字打出、计数这类内容变化在 draw 里按 t 画。

const STYLE = {
  color: {
    bg: "#0A0F1A",
    panel: "rgba(120,160,220,0.06)",
    grid: "rgba(120,160,220,0.07)",
    text: "#E6EDF7",
    muted: "#7C8BA1",
    accent: "#3BE0A0", // 主强调：状态、进度、结果
    info: "#4DA3FF", // 语义色：仅用于第二条数据或链接，和强调色不同时大面积出现
  },
  font: {
    title: '"HarmonyOS Sans SC", "MiSans", "Source Han Sans SC", "Microsoft YaHei", sans-serif',
    // 等宽链后面接黑体：等宽小字里的中文回退到主字体，不落成宋体。
    mono: '"JetBrains Mono", "Cascadia Mono", "Consolas", "HarmonyOS Sans SC", "Microsoft YaHei", monospace',
  },
};

// 分场景硬切：每个切点一条强调色竖线从左扫到右（0.28 s），线左边已是新场景，线右边还是旧场景。
const WIPE = 0.28;
const CUTS = [1.9, 3.6, 6.2, 8.1, 9.5];
const SCENES = { title: [0, CUTS[0]], keyword: [CUTS[0], CUTS[1]], media: [CUTS[1], CUTS[2]], data: [CUTS[2], CUTS[3]], name: [CUTS[3], CUTS[4]], end: [CUTS[4], 99] };
const COPY = {
  title: "把想法变成画面",
  keyword: { lead: "风格", key: "不走样" },
  media: "示意画面",
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: "一个风格，处处一致",
};

const clamp = (v) => Math.max(0, Math.min(1, v));
const quartOut = (v) => 1 - Math.pow(1 - clamp(v), 4);
const quintOut = (v) => 1 - Math.pow(1 - clamp(v), 5);
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 新场景比扫线早 0.12 s 开始进场（还藏在线后），被线揭开时元素已经在动；入场 0.45 s quartOut；离场不做动画，由下一条扫线切走。
const LEAD = 0.12;
const start = ([a]) => (a > 0 ? a - WIPE / 2 - LEAD : 0);
const enter = (t, scene, delay = 0, dur = 0.45) => quartOut((t - start(scene) - delay) / dur);
const visible = (t, [a, b]) => t >= start([a]) && t < b + WIPE / 2;
const wipeX = (t, cut, w) => w * quartOut((t - (cut - WIPE / 2)) / WIPE);
// 本场景在扫线期间的可见范围：进场时只在线左边，被切走时只在线右边。
function cutClip(t, [a, b], w, h) {
  if (a > 0 && t < a + WIPE / 2) return [0, 0, wipeX(t, a, w), h];
  if (t >= b - WIPE / 2) return [wipeX(t, b, w), 0, w, h];
  return null;
}
const meet = (a, b) => (!a ? b : !b ? a : [Math.max(a[0], b[0]), Math.max(a[1], b[1]), Math.min(a[2], b[2]), Math.min(a[3], b[3])]);

function grid(ctx, t, u, w, h) {
  const step = 40 * u;
  // 网格极慢平移，只做底纹，不抢主体。
  const off = (t * 6 * u) % step;
  ctx.fillStyle = STYLE.color.grid;
  for (let x = -off; x < w; x += step) ctx.fillRect(x, 0, Math.max(1, u), h);
  for (let y = -off; y < h; y += step) ctx.fillRect(0, y, w, Math.max(1, u));
  const fade = ctx.createLinearGradient(0, 0, 0, h);
  fade.addColorStop(0, "rgba(10,15,26,0.85)");
  fade.addColorStop(0.35, "rgba(10,15,26,0)");
  fade.addColorStop(0.65, "rgba(10,15,26,0)");
  fade.addColorStop(1, "rgba(10,15,26,0.85)");
  ctx.fillStyle = fade;
  ctx.fillRect(0, 0, w, h);
}

// 四角角标：线段从角向两边长出（k 0→1）。
function brackets(ctx, x, y, bw, bh, len, k, u, color = STYLE.color.accent) {
  const l = len * k, lw = Math.max(1, 1.5 * u);
  ctx.fillStyle = color;
  for (const [cx, cy, sx, sy] of [[x, y, 1, 1], [x + bw, y, -1, 1], [x, y + bh, 1, -1], [x + bw, y + bh, -1, -1]]) {
    ctx.fillRect(sx > 0 ? cx : cx - l, cy - (sy > 0 ? 0 : lw), l, lw);
    ctx.fillRect(cx - (sx > 0 ? 0 : lw), sy > 0 ? cy : cy - l, lw, l);
  }
}

// 等宽逐字打出，末尾带光标块；打完后光标再留一会儿。
function typeOn(ctx, text, x, y, k, u, size) {
  const n = Math.floor(text.length * clamp(k));
  ctx.fillText(text.slice(0, n), x, y);
  if (k > 0 && k < 1.6) {
    const cw = ctx.measureText(text.slice(0, n)).width;
    ctx.fillRect(x + cw + 2 * u, y - size * 0.8, size * 0.5, size * 0.95);
  }
}

// 勾选框：先描框，再从左向右填实（表示“完成”）。
function checkbox(ctx, x, y, size, k, u) {
  ctx.strokeStyle = STYLE.color.accent;
  ctx.lineWidth = 1.5 * u;
  ctx.strokeRect(x, y, size, size);
  const fill = clamp((k - 0.4) / 0.6);
  ctx.fillStyle = STYLE.color.accent;
  ctx.fillRect(x + 5 * u, y + 5 * u, (size - 10 * u) * fill, size - 10 * u);
}

function rollNumber(value, k) {
  return (value * quintOut(k)).toFixed(1);
}

// 扫线：一条强调色竖线带一小段淡尾，本地坐标原点在竖线上，位置由 pose 给出。
function wipe(ctx, u, h) {
  ctx.fillStyle = STYLE.color.accent;
  ctx.fillRect(0, 0, 2 * u, h);
  ctx.fillStyle = "rgba(59,224,160,0.08)";
  ctx.fillRect(-60 * u, 0, 60 * u, h);
}

function lineChart(ctx, x, y, cw, ch, k, u) {
  const pts = [0.12, 0.2, 0.18, 0.34, 0.31, 0.46, 0.58, 0.55, 0.71, 0.87];
  ctx.strokeStyle = STYLE.color.grid;
  ctx.lineWidth = Math.max(1, u);
  for (let i = 0; i <= 4; i++) { ctx.beginPath(); ctx.moveTo(x, y + (ch * i) / 4); ctx.lineTo(x + cw, y + (ch * i) / 4); ctx.stroke(); }
  const n = (pts.length - 1) * clamp(k);
  ctx.strokeStyle = STYLE.color.accent;
  ctx.lineWidth = 2.5 * u;
  ctx.lineJoin = "round";
  ctx.beginPath();
  let px = x, py = y + ch;
  for (let i = 0; i <= Math.floor(n); i++) {
    px = x + (cw * i) / (pts.length - 1); py = y + ch * (1 - pts[i]);
    i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
  }
  const f = n - Math.floor(n), i = Math.floor(n);
  if (i < pts.length - 1) {
    px += (cw / (pts.length - 1)) * f;
    py = y + ch * (1 - (pts[i] + (pts[i + 1] - pts[i]) * f));
    ctx.lineTo(px, py);
  }
  ctx.stroke();
  // 末端光点：只有数据末端允许一圈很淡的同色光晕。
  ctx.fillStyle = STYLE.color.accent;
  ctx.beginPath(); ctx.arc(px, py, 5 * u, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "rgba(59,224,160,0.2)";
  ctx.beginPath(); ctx.arc(px, py, 12 * u, 0, Math.PI * 2); ctx.fill();
}

// 示意画面：一块深色的编辑界面（预览、属性栏、时间线），本地坐标原点在左上角；高亮目标是属性栏里的按钮。
function mockTarget(iw, ih) { return { x: iw * 0.7, y: ih * 0.47, w: iw * 0.22, h: ih * 0.08 }; }
function mockScreen(ctx, iw, ih, u) {
  ctx.fillStyle = "#16223A"; ctx.fillRect(0, 0, iw, ih);
  ctx.fillStyle = "#1C2A45"; ctx.fillRect(0, 0, iw, ih * 0.075);
  for (let i = 0; i < 3; i++) { ctx.fillStyle = "#33425F"; ctx.fillRect((12 + i * 14) * u, ih * 0.025, 8 * u, 8 * u); }
  const px = iw * 0.035, py = ih * 0.12, pw = iw * 0.6, ph = ih * 0.55;
  const sky = ctx.createLinearGradient(0, py, 0, py + ph);
  sky.addColorStop(0, "#26406A"); sky.addColorStop(1, "#18253D");
  ctx.fillStyle = sky; ctx.fillRect(px, py, pw, ph);
  ctx.save(); ctx.beginPath(); ctx.rect(px, py, pw, ph); ctx.clip();
  ctx.strokeStyle = "rgba(120,160,220,0.12)"; ctx.lineWidth = Math.max(1, u);
  for (let i = 1; i < 6; i++) { ctx.beginPath(); ctx.moveTo(px + (pw * i) / 6, py); ctx.lineTo(px + (pw * i) / 6, py + ph); ctx.stroke(); }
  ctx.fillStyle = "rgba(230,237,247,0.7)"; ctx.beginPath(); ctx.arc(px + pw * 0.7, py + ph * 0.36, ph * 0.09, 0, Math.PI * 2); ctx.fill();
  const hill = (k, color, lift) => {
    ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(px, py + ph);
    for (let i = 0; i <= 10; i++) ctx.lineTo(px + (pw * i) / 10, py + ph * (lift - 0.1 * Math.sin(i * 1.1 + k)));
    ctx.lineTo(px + pw, py + ph); ctx.closePath(); ctx.fill();
  };
  hill(0.4, "#2A4470", 0.7); hill(2.2, "#1B2B48", 0.86);
  ctx.restore();
  const sx = iw * 0.67, sw = iw * 0.29;
  [0.9, 0.55, 0.75, 0.45].forEach((k, i) => { ctx.fillStyle = "#2A3956"; ctx.fillRect(sx, py + ih * (0.02 + i * 0.07), sw * k, ih * 0.022); });
  const T = mockTarget(iw, ih);
  ctx.strokeStyle = "#3BE0A0"; ctx.lineWidth = 1.5 * u; ctx.strokeRect(T.x, T.y, T.w, T.h);
  ctx.fillStyle = "rgba(59,224,160,0.14)"; ctx.fillRect(T.x, T.y, T.w, T.h);
  ctx.fillStyle = "#3BE0A0"; ctx.fillRect(T.x + T.w * 0.25, T.y + T.h * 0.43, T.w * 0.5, T.h * 0.16);
  const ty = py + ph + ih * 0.07, lanes = [[0, 0.3, 0.32, 0.36], [0.06, 0.48, 0.58, 0.3], [0, 0.22, 0.26, 0.5]];
  lanes.forEach((row, i) => { for (let j = 0; j < row.length; j += 2) { ctx.fillStyle = i === 1 ? "#22505A" : "#22314D"; ctx.fillRect(px + (iw * 0.93) * row[j], ty + i * ih * 0.055, (iw * 0.93) * row[j + 1], ih * 0.035); } });
}

// 只用来量字宽（分层时还没有画布）。
let measurer = null;
function measure(text, f) {
  measurer ??= new OffscreenCanvas(1, 1).getContext("2d");
  measurer.font = f;
  return measurer.measureText(text).width;
}

function layers(_params, w, h, _assets, info) {
  const u = h / 720, out = [], x = w * 0.1, C = STYLE.color, F = STYLE.font;
  const now = info?.time ?? 0;
  // 把一个场景的所有层包上扫线裁切：扫线期间只在线的一侧可见；场景外不画。
  const scene = (sc, layer) => {
    const clip = meet(layer.clip, cutClip(now, sc, w, h));
    if (layer.pose) return { ...layer, clip: clip ?? undefined, pose: (t) => (visible(t, sc) ? layer.pose(t) : null) };
    return { ...layer, clip: clip ?? undefined, draw: (ctx, t) => { if (visible(t, sc)) layer.draw(ctx, t); } };
  };
  // 底：底色与缓慢平移的网格，整层按当前时刻画，贯穿所有切点。
  out.push({ draw: (ctx, t) => { ctx.fillStyle = C.bg; ctx.fillRect(0, 0, w, h); grid(ctx, t, u, w, h); } });

  // 标题：角标框从四角长出框住整组（标题框）→ 等宽编号逐字打出 → 粗体标题从遮罩左侧滑入。不加副标题。
  const title = SCENES.title, ty = h * 0.5, titleFont = font(700, 66 * u, F.title), titleW = measure(COPY.title, titleFont);
  out.push(scene(title, {
    draw: (ctx, t) => {
      ctx.fillStyle = C.accent; ctx.font = font(500, 15 * u, F.mono);
      typeOn(ctx, "[01]", x, ty - 70 * u, (t - 0.05) / 0.3, u, 15 * u);
      brackets(ctx, x - 28 * u, ty - 112 * u, titleW + 56 * u, 156 * u, 22 * u, enter(t, title, 0.1), u);
    },
  }));
  out.push(scene(title, {
    bounds: [0, -70 * u, titleW + 10 * u, 20 * u],
    clip: [x, ty - 70 * u, w, ty + 20 * u],
    pose: (t) => ({ x: x - (1 - enter(t, title, 0.15)) * 120 * u, y: ty }),
    draw: (ctx) => { ctx.fillStyle = C.text; ctx.font = titleFont; ctx.fillText(COPY.title, 0, 0); },
  }));

  // 花字与关键词：淡面板条先向右伸出（先出框）→ 勾选框描框后填实 → 文字从右侧滑入，“不走样”下方一条强调色线生长。
  // 强调色在这里表示“结果”：勾上了、做到了。
  const kw = SCENES.keyword, ky = h * 0.53, leadFont = font(500, 40 * u, F.title), keyFont = font(700, 88 * u, F.title);
  const leadW = measure(COPY.keyword.lead, leadFont), keyW = measure(COPY.keyword.key, keyFont), box = 34 * u;
  const tx = x + box + 34 * u, keyX = tx + leadW + 20 * u, rw = keyX + keyW + 48 * u - x;
  out.push(scene(kw, {
    bounds: [0, 0, rw, 132 * u],
    pose: (t) => { const e = enter(t, kw, 0, 0.4); return e > 0.002 ? { x, y: ky - 90 * u, scaleX: e, scaleY: 1 } : null; },
    draw: (ctx) => { ctx.fillStyle = C.panel; ctx.fillRect(0, 0, rw, 132 * u); ctx.fillStyle = C.grid; ctx.fillRect(0, 132 * u, rw, Math.max(1, u)); },
  }));
  out.push(scene(kw, { draw: (ctx, t) => checkbox(ctx, x + 22 * u, ky - 41 * u, box, (t - start(kw) - 0.25) / 0.35, u) }));
  out.push(scene(kw, {
    bounds: [0, -80 * u, keyX - tx + keyW, 12 * u],
    pose: (t) => { const e = enter(t, kw, 0.12); return e > 0 ? { x: tx + (1 - e) * 40 * u, y: ky, opacity: clamp(e * 3) } : null; },
    draw: (ctx) => {
      ctx.fillStyle = C.muted; ctx.font = leadFont; ctx.fillText(COPY.keyword.lead, 0, 0);
      ctx.fillStyle = C.text; ctx.font = keyFont; ctx.fillText(COPY.keyword.key, keyX - tx, 0);
    },
  }));
  out.push(scene(kw, {
    bounds: [0, 0, 100, 4 * u],
    pose: (t) => { const e = enter(t, kw, 0.45, 0.4); return e > 0.002 ? { x: keyX, y: ky + 16 * u, scaleX: (keyW / 100) * e, scaleY: 1 } : null; },
    draw: (ctx) => { ctx.fillStyle = C.accent; ctx.fillRect(0, 0, 100, 4 * u); },
  }));

  // 图片与录屏容器 + 高亮：截图不加边框，四角灰色角标框住它（截图从右侧快速滑入落位，角标随后长出）。
  // 高亮：角标变成强调色，一起收拢到目标按钮四周（quartOut 0.45 s），目标以外压暗一层。
  const media = SCENES.media, iw = w * 0.6, ih = iw * 9 / 16, ix = (w - iw) / 2, iy = h * 0.53 - ih / 2, T = mockTarget(iw, ih);
  const hlAt = start(media) + 1.2, hl = (t) => quartOut((t - hlAt) / 0.45);
  out.push(scene(media, {
    bounds: [0, 0, iw, ih],
    pose: (t) => { const e = enter(t, media, 0.05, 0.5); return e > 0 ? { x: ix + (1 - e) * 90 * u, y: iy, opacity: clamp(e * 3) } : null; },
    draw: (ctx) => mockScreen(ctx, iw, ih, u),
  }));
  out.push(scene(media, {
    draw: (ctx, t) => {
      const k = hl(t);
      if (k > 0) {
        ctx.beginPath(); ctx.rect(ix, iy, iw, ih); ctx.rect(ix + T.x - 8 * u, iy + T.y - 8 * u, T.w + 16 * u, T.h + 16 * u);
        ctx.fillStyle = `rgba(10,15,26,${0.45 * k})`; ctx.fill("evenodd");
      }
      ctx.fillStyle = C.muted; ctx.font = font(500, 13 * u, F.mono);
      typeOn(ctx, COPY.media, ix, iy - 16 * u, (t - start(media) - 0.35) / 0.25, u, 13 * u);
    },
  }));
  out.push(scene(media, {
    bounds: [-20 * u, -20 * u, iw + 20 * u, ih + 20 * u],
    pose: (t) => (enter(t, media, 0.3) > 0 ? { x: ix, y: iy } : null),
    draw: (ctx, t) => {
      const k = hl(t), g = enter(t, media, 0.3), pad = 16 * u - 8 * u * k;
      const bx = (T.x - pad) * k - pad * (1 - k), by = (T.y - pad) * k - pad * (1 - k);
      const bw = (T.w + 2 * pad) * k + (iw + 2 * pad) * (1 - k), bh = (T.h + 2 * pad) * k + (ih + 2 * pad) * (1 - k);
      brackets(ctx, bx, by, bw, bh, (22 - 8 * k) * u, g, u, k > 0.05 ? C.accent : C.muted);
    },
  }));

  // 数据：等宽大数字滚动（保留一位小数，宽度不跳）+ 强调色单位；右侧角标框住的折线随数字一起生长，末端光点。
  const data = SCENES.data;
  out.push(scene(data, {
    draw: (ctx, t) => {
      const k = (t - start(data) - 0.1) / 1.2;
      ctx.fillStyle = C.muted; ctx.font = font(500, 18 * u, F.title);
      ctx.fillText(COPY.data.label, x, h * 0.3);
      ctx.fillStyle = C.text; ctx.font = font(700, 120 * u, F.mono);
      const num = rollNumber(COPY.data.value, k);
      ctx.fillText(num, x, h * 0.3 + 128 * u);
      const nw = ctx.measureText(num).width;
      ctx.fillStyle = C.accent; ctx.font = font(500, 40 * u, F.mono);
      ctx.fillText(COPY.data.unit, x + nw + 10 * u, h * 0.3 + 128 * u);
      lineChart(ctx, w * 0.52, h * 0.3, w * 0.38, h * 0.4, k, u);
      brackets(ctx, w * 0.52 - 16 * u, h * 0.3 - 16 * u, w * 0.38 + 32 * u, h * 0.4 + 32 * u, 14 * u, enter(t, data), u, C.muted);
    },
  }));

  // 人名条：深色底条向右展开（scaleX），左侧强调色竖条向下长出，名字与职位随底条从左滑入。
  const name = SCENES.name, ny = h * 0.72, bw = 300 * u, bh = 84 * u;
  out.push(scene(name, {
    bounds: [0, 0, bw, bh],
    pose: (t) => { const e = enter(t, name, 0, 0.4); return e > 0.002 ? { x, y: ny, scaleX: e, scaleY: 1 } : null; },
    draw: (ctx) => { ctx.fillStyle = "rgba(20,29,47,0.92)"; ctx.fillRect(0, 0, bw, bh); },
  }));
  out.push(scene(name, {
    bounds: [0, 0, 4 * u, bh],
    pose: (t) => { const e = enter(t, name, 0.05, 0.35); return e > 0.002 ? { x, y: ny, scaleX: 1, scaleY: e } : null; },
    draw: (ctx) => { ctx.fillStyle = C.accent; ctx.fillRect(0, 0, 4 * u, bh); },
  }));
  out.push(scene(name, {
    clip: [x + 4 * u, ny, x + bw, ny + bh],
    bounds: [0, 0, bw, bh],
    pose: (t) => { const e = enter(t, name, 0.1); return { x: x - (1 - e) * 80 * u, y: ny }; },
    draw: (ctx) => {
      ctx.fillStyle = C.text; ctx.font = font(700, 30 * u, F.title); ctx.fillText(COPY.name.name, 24 * u, 40 * u);
      ctx.fillStyle = C.muted; ctx.font = font(400, 16 * u, F.title); ctx.fillText(COPY.name.role, 24 * u, 66 * u);
    },
  }));

  // 收尾：一句话从右侧滑入落在中间，角标框从四角长出框住它。
  const end = SCENES.end, endFont = font(700, 48 * u, F.title), endW = measure(COPY.end, endFont);
  out.push(scene(end, {
    bounds: [-endW / 2 - 10 * u, -44 * u, endW / 2 + 10 * u, 14 * u],
    pose: (t) => { const e = enter(t, end, 0.05); return { x: w / 2 + (1 - e) * 60 * u, y: h / 2 + 16 * u, opacity: clamp(e * 3) }; },
    draw: (ctx) => { ctx.textAlign = "center"; ctx.fillStyle = C.text; ctx.font = endFont; ctx.fillText(COPY.end, 0, 0); ctx.textAlign = "left"; },
  }));
  out.push(scene(end, { draw: (ctx, t) => brackets(ctx, w / 2 - endW / 2 - 48 * u, h / 2 - 62 * u, endW + 96 * u, 124 * u, 20 * u, enter(t, end, 0.2), u) }));

  // 扫线：每个切点从左到右扫过整个画面，速度很快，模糊最明显。
  for (const cut of CUTS) {
    out.push({
      bounds: [-60 * u, 0, 2 * u, h],
      pose: (t) => { const k = clamp((t - (cut - WIPE / 2)) / WIPE); return k > 0 && k < 1 ? { x: w * quartOut(k), y: 0 } : null; },
      draw: (ctx) => wipe(ctx, u, h),
    });
  }
  return out;
}

